    col += mix((1.0 - nrm), nrm.zxy, flip) * 0.12 * B + neonC * B;   // \u53CD\u8EE2\u6CD5\u7DDA\u306E\u5730\u8272\u3082\u914D\u8272\u3054\u3068\u5165\u308C\u66FF\u308F\u308B
    col = min(col, vec3(0.8));
